    CREATE TABLE IF NOT EXISTS `notification_campaigns` (
    `id` INT NOT NULL AUTO_INCREMENT,
    `sender_user_id` INT NULL,
    `kind` ENUM('staff','support','workflow','system') NOT NULL DEFAULT 'system',
    `support_category` ENUM('Ask RPMS Staff','Report a Problem','Account/Access','Document/Submission','IERB Progress','Technical Issue','Other') NULL,
    `reply_to_campaign_id` INT NULL,
    `subject` VARCHAR(255) NULL,
    `message` TEXT NULL,
    `status` VARCHAR(20) NOT NULL DEFAULT 'Scheduled',
    `scheduled_at` DATETIME NULL,
    `sent_at` DATETIME NULL,
    `archived_at` DATETIME NULL,
    `deleted_at` DATETIME NULL,
    `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `campaign_sender` (`sender_user_id`,`created_at`),
    KEY `campaign_reply` (`reply_to_campaign_id`),
    CONSTRAINT `campaign_sender_fk` FOREIGN KEY (`sender_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
    CONSTRAINT `campaign_reply_fk` FOREIGN KEY (`reply_to_campaign_id`) REFERENCES `notification_campaigns` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
    CREATE TABLE IF NOT EXISTS `legal_policies` (
    `id` ENUM('privacy','terms') NOT NULL,
    `current_version_id` INT NULL,
    PRIMARY KEY (`id`),
    KEY `policy_current` (`id`,`current_version_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
    CREATE TABLE IF NOT EXISTS `legal_policy_versions` (
    `id` INT NOT NULL AUTO_INCREMENT,
    `policy_id` ENUM('privacy','terms') NOT NULL,
    `version_number` INT NOT NULL,
    `title` VARCHAR(190) NOT NULL,
    `content` MEDIUMTEXT NOT NULL,
    `change_summary` VARCHAR(500) NOT NULL DEFAULT '',
    `state` ENUM('draft','pending','rejected','published') NOT NULL DEFAULT 'draft',
    `open_candidate` TINYINT GENERATED ALWAYS AS (CASE WHEN state IN ('draft','pending') THEN 1 ELSE NULL END) STORED,
    `content_sha256` CHAR(64) NOT NULL,
    `creator_user_id` INT NULL,
    `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `submitted_at` DATETIME NULL,
    `published_at` DATETIME NULL,
    PRIMARY KEY (`id`),
    UNIQUE KEY `policy_version_number` (`policy_id`,`version_number`),
    UNIQUE KEY `policy_version_identity` (`policy_id`,`id`),
    UNIQUE KEY `policy_open_candidate` (`policy_id`,`open_candidate`),
    KEY `policy_creator` (`creator_user_id`),
    CONSTRAINT `version_policy_fk` FOREIGN KEY (`policy_id`) REFERENCES `legal_policies` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT `version_creator_fk` FOREIGN KEY (`creator_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
    CREATE TABLE IF NOT EXISTS `legal_policy_approvals` (
    `id` INT NOT NULL AUTO_INCREMENT,
    `version_id` INT NOT NULL,
    `reviewer_user_id` INT NULL,
    `decision` ENUM('approved','rejected') NOT NULL,
    `approval_mode` ENUM('independent','sole_admin','bootstrap') NOT NULL,
    `reason` VARCHAR(500) NULL,
    `reviewed_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `approval_version` (`version_id`),
    KEY `approval_reviewer` (`reviewer_user_id`),
    CONSTRAINT `approval_version_fk` FOREIGN KEY (`version_id`) REFERENCES `legal_policy_versions` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT `approval_reviewer_fk` FOREIGN KEY (`reviewer_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
    CREATE TABLE IF NOT EXISTS `user_policy_acceptances` (
    `user_id` INT NOT NULL,
    `policy_version_id` INT NOT NULL,
    `accepted_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`user_id`,`policy_version_id`),
    KEY `acceptance_version` (`policy_version_id`),
    CONSTRAINT `acceptance_user_fk` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
    CONSTRAINT `acceptance_version_fk` FOREIGN KEY (`policy_version_id`) REFERENCES `legal_policy_versions` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
    CREATE TABLE IF NOT EXISTS `staff_registration_code` (
    `slot` TINYINT NOT NULL DEFAULT 1,
    `generation_id` CHAR(32) NOT NULL,
    `verifier_hash` VARCHAR(255) NULL,
    `state` ENUM('pending','acknowledged','invalidated','expired','consumed') NOT NULL DEFAULT 'pending',
    `creator_user_id` INT NULL,
    `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `acknowledged_at` DATETIME NULL,
    `expires_at` DATETIME NULL,
    `consumed_at` DATETIME NULL,
    `consumed_by_user_id` INT NULL,
    PRIMARY KEY (`slot`),
    UNIQUE KEY `staff_code_generation` (`generation_id`),
    KEY `staff_code_creator` (`creator_user_id`),
    KEY `staff_code_consumer` (`consumed_by_user_id`),
    CONSTRAINT `staff_code_creator_fk` FOREIGN KEY (`creator_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
    CONSTRAINT `staff_code_consumer_fk` FOREIGN KEY (`consumed_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
    CONSTRAINT staff_code_singleton CHECK (slot = 1)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
