    IF (SELECT COUNT(*) FROM (SELECT INDEX_NAME FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='staff_registration_code' AND INDEX_NAME='PRIMARY' AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL GROUP BY INDEX_NAME HAVING GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX)='slot' AND MIN(NON_UNIQUE)=0 AND MAX(NON_UNIQUE)=0) AS checked_index)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='v10 contract: staff_registration_code.PRIMARY'; END IF;
