    IF (SELECT COUNT(*) FROM (SELECT INDEX_NAME FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='staff_registration_code' AND INDEX_NAME='staff_code_creator' AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL GROUP BY INDEX_NAME HAVING GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX)='creator_user_id' AND MIN(NON_UNIQUE)=1 AND MAX(NON_UNIQUE)=1) AS checked_index)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='v10 contract: staff_registration_code.staff_code_creator'; END IF;
    IF (SELECT COUNT(*) FROM (SELECT INDEX_NAME FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='staff_registration_code' AND INDEX_NAME='staff_code_consumer' AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL GROUP BY INDEX_NAME HAVING GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX)='consumed_by_user_id' AND MIN(NON_UNIQUE)=1 AND MAX(NON_UNIQUE)=1) AS checked_index)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='v10 contract: staff_registration_code.staff_code_consumer'; END IF;
    IF (SELECT COUNT(*) FROM (SELECT k.CONSTRAINT_NAME FROM INFORMATION_SCHEMA.KEY_COLUMN_USAGE k JOIN INFORMATION_SCHEMA.REFERENTIAL_CONSTRAINTS r ON r.CONSTRAINT_SCHEMA=k.CONSTRAINT_SCHEMA AND r.TABLE_NAME=k.TABLE_NAME AND r.CONSTRAINT_NAME=k.CONSTRAINT_NAME WHERE k.TABLE_SCHEMA=DATABASE() AND k.TABLE_NAME='staff_registration_code' AND k.CONSTRAINT_NAME='staff_code_creator_fk' AND k.REFERENCED_TABLE_SCHEMA=DATABASE() AND k.REFERENCED_TABLE_NAME='users' AND r.DELETE_RULE='SET NULL' AND r.UPDATE_RULE='RESTRICT' GROUP BY k.CONSTRAINT_NAME HAVING GROUP_CONCAT(k.COLUMN_NAME ORDER BY k.ORDINAL_POSITION)='creator_user_id' AND GROUP_CONCAT(k.REFERENCED_COLUMN_NAME ORDER BY k.ORDINAL_POSITION)='id') AS checked_fk)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='v10 contract: staff_registration_code.staff_code_creator_fk'; END IF;
    IF (SELECT COUNT(*) FROM (SELECT k.CONSTRAINT_NAME FROM INFORMATION_SCHEMA.KEY_COLUMN_USAGE k JOIN INFORMATION_SCHEMA.REFERENTIAL_CONSTRAINTS r ON r.CONSTRAINT_SCHEMA=k.CONSTRAINT_SCHEMA AND r.TABLE_NAME=k.TABLE_NAME AND r.CONSTRAINT_NAME=k.CONSTRAINT_NAME WHERE k.TABLE_SCHEMA=DATABASE() AND k.TABLE_NAME='staff_registration_code' AND k.CONSTRAINT_NAME='staff_code_consumer_fk' AND k.REFERENCED_TABLE_SCHEMA=DATABASE() AND k.REFERENCED_TABLE_NAME='users' AND r.DELETE_RULE='SET NULL' AND r.UPDATE_RULE='RESTRICT' GROUP BY k.CONSTRAINT_NAME HAVING GROUP_CONCAT(k.COLUMN_NAME ORDER BY k.ORDINAL_POSITION)='consumed_by_user_id' AND GROUP_CONCAT(k.REFERENCED_COLUMN_NAME ORDER BY k.ORDINAL_POSITION)='id') AS checked_fk)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='v10 contract: staff_registration_code.staff_code_consumer_fk'; END IF;
    IF (SELECT COUNT(*) FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='notifications' AND ENGINE='InnoDB')<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='v10 contract: notifications engine'; END IF;
    IF (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='notifications' AND COLUMN_NAME='campaign_id' AND REPLACE(REPLACE(LOWER(COLUMN_TYPE),'int(11)','int'),'tinyint(4)','tinyint')='int' AND IS_NULLABLE='YES' AND REPLACE(LOWER(COALESCE(NULLIF(TRIM(BOTH CHAR(39) FROM COLUMN_DEFAULT),'NULL'),'<null>')),'current_timestamp()','current_timestamp')='<null>')<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='v10 contract: notifications.campaign_id'; END IF;
    IF (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='notifications' AND COLUMN_NAME='recipient_user_id' AND REPLACE(REPLACE(LOWER(COLUMN_TYPE),'int(11)','int'),'tinyint(4)','tinyint')='int' AND IS_NULLABLE='YES' AND REPLACE(LOWER(COALESCE(NULLIF(TRIM(BOTH CHAR(39) FROM COLUMN_DEFAULT),'NULL'),'<null>')),'current_timestamp()','current_timestamp')='<null>')<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='v10 contract: notifications.recipient_user_id'; END IF;
    IF (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='notifications' AND COLUMN_NAME='archived_at' AND REPLACE(REPLACE(LOWER(COLUMN_TYPE),'int(11)','int'),'tinyint(4)','tinyint')='datetime' AND IS_NULLABLE='YES' AND REPLACE(LOWER(COALESCE(NULLIF(TRIM(BOTH CHAR(39) FROM COLUMN_DEFAULT),'NULL'),'<null>')),'current_timestamp()','current_timestamp')='<null>')<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='v10 contract: notifications.archived_at'; END IF;
    IF (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='notifications' AND COLUMN_NAME='deleted_at' AND REPLACE(REPLACE(LOWER(COLUMN_TYPE),'int(11)','int'),'tinyint(4)','tinyint')='datetime' AND IS_NULLABLE='YES' AND REPLACE(LOWER(COALESCE(NULLIF(TRIM(BOTH CHAR(39) FROM COLUMN_DEFAULT),'NULL'),'<null>')),'current_timestamp()','current_timestamp')='<null>')<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='v10 contract: notifications.deleted_at'; END IF;
    IF (SELECT COUNT(*) FROM (SELECT INDEX_NAME FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='notifications' AND INDEX_NAME='notification_campaign' AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL GROUP BY INDEX_NAME HAVING GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX)='campaign_id' AND MIN(NON_UNIQUE)=1 AND MAX(NON_UNIQUE)=1) AS checked_index)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='v10 contract: notifications.notification_campaign'; END IF;
    IF (SELECT COUNT(*) FROM (SELECT INDEX_NAME FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='notifications' AND INDEX_NAME='notification_user' AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL GROUP BY INDEX_NAME HAVING GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX)='recipient_user_id,created_at' AND MIN(NON_UNIQUE)=1 AND MAX(NON_UNIQUE)=1) AS checked_index)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='v10 contract: notifications.notification_user'; END IF;
    IF (SELECT COUNT(*) FROM (SELECT k.CONSTRAINT_NAME FROM INFORMATION_SCHEMA.KEY_COLUMN_USAGE k JOIN INFORMATION_SCHEMA.REFERENTIAL_CONSTRAINTS r ON r.CONSTRAINT_SCHEMA=k.CONSTRAINT_SCHEMA AND r.TABLE_NAME=k.TABLE_NAME AND r.CONSTRAINT_NAME=k.CONSTRAINT_NAME WHERE k.TABLE_SCHEMA=DATABASE() AND k.TABLE_NAME='notifications' AND k.CONSTRAINT_NAME='notification_campaign_fk' AND k.REFERENCED_TABLE_SCHEMA=DATABASE() AND k.REFERENCED_TABLE_NAME='notification_campaigns' AND r.DELETE_RULE='SET NULL' AND r.UPDATE_RULE='RESTRICT' GROUP BY k.CONSTRAINT_NAME HAVING GROUP_CONCAT(k.COLUMN_NAME ORDER BY k.ORDINAL_POSITION)='campaign_id' AND GROUP_CONCAT(k.REFERENCED_COLUMN_NAME ORDER BY k.ORDINAL_POSITION)='id') AS checked_fk)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='v10 contract: notifications.notification_campaign_fk'; END IF;
    IF (SELECT COUNT(*) FROM (SELECT k.CONSTRAINT_NAME FROM INFORMATION_SCHEMA.KEY_COLUMN_USAGE k JOIN INFORMATION_SCHEMA.REFERENTIAL_CONSTRAINTS r ON r.CONSTRAINT_SCHEMA=k.CONSTRAINT_SCHEMA AND r.TABLE_NAME=k.TABLE_NAME AND r.CONSTRAINT_NAME=k.CONSTRAINT_NAME WHERE k.TABLE_SCHEMA=DATABASE() AND k.TABLE_NAME='notifications' AND k.CONSTRAINT_NAME='notification_user_fk' AND k.REFERENCED_TABLE_SCHEMA=DATABASE() AND k.REFERENCED_TABLE_NAME='users' AND r.DELETE_RULE='CASCADE' AND r.UPDATE_RULE='RESTRICT' GROUP BY k.CONSTRAINT_NAME HAVING GROUP_CONCAT(k.COLUMN_NAME ORDER BY k.ORDINAL_POSITION)='recipient_user_id' AND GROUP_CONCAT(k.REFERENCED_COLUMN_NAME ORDER BY k.ORDINAL_POSITION)='id') AS checked_fk)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='v10 contract: notifications.notification_user_fk'; END IF;
