    START TRANSACTION;
    INSERT INTO legal_policies (id) SELECT 'privacy' WHERE NOT EXISTS (SELECT 1 FROM legal_policies WHERE id='privacy');
    INSERT INTO legal_policy_versions (policy_id,version_number,title,content,change_summary,state,content_sha256,submitted_at,published_at) SELECT 'privacy',1,'Privacy Policy',CONVERT( USING utf8mb4),'Corrected approved Batch 5B source','published','4d1c161153fa0892ccbb4133ec0ee6155378ef05823e45a9d894484471fcda31',NOW(),NOW() WHERE NOT EXISTS (SELECT 1 FROM legal_policy_versions WHERE policy_id='privacy' AND version_number=1);
    INSERT INTO legal_policy_approvals (version_id,decision,approval_mode,reason) SELECT id,'approved','bootstrap','Approved Batch 5B checkpoint; no user acceptance implied' FROM legal_policy_versions v WHERE policy_id='privacy' AND version_number=1 AND NOT EXISTS (SELECT 1 FROM legal_policy_approvals a WHERE a.version_id=v.id);
    UPDATE legal_policies p JOIN legal_policy_versions v ON v.policy_id=p.id AND v.version_number=1 SET p.current_version_id=v.id WHERE p.id='privacy' AND p.current_version_id IS NULL AND NOT EXISTS (SELECT 1 FROM legal_policy_versions newer WHERE newer.policy_id=p.id AND newer.version_number>1);
    INSERT INTO legal_policies (id) SELECT 'terms' WHERE NOT EXISTS (SELECT 1 FROM legal_policies WHERE id='terms');
    INSERT INTO legal_policy_versions (policy_id,version_number,title,content,change_summary,state,content_sha256,submitted_at,published_at) SELECT 'terms',1,'Terms of Service',CONVERT( USING utf8mb4),'Corrected approved Batch 5B source','published','4fabda0f307ed19036dea0af01db77a6ca0513911b7cfcbea20b1658e958aec8',NOW(),NOW() WHERE NOT EXISTS (SELECT 1 FROM legal_policy_versions WHERE policy_id='terms' AND version_number=1);
    INSERT INTO legal_policy_approvals (version_id,decision,approval_mode,reason) SELECT id,'approved','bootstrap','Approved Batch 5B checkpoint; no user acceptance implied' FROM legal_policy_versions v WHERE policy_id='terms' AND version_number=1 AND NOT EXISTS (SELECT 1 FROM legal_policy_approvals a WHERE a.version_id=v.id);
    UPDATE legal_policies p JOIN legal_policy_versions v ON v.policy_id=p.id AND v.version_number=1 SET p.current_version_id=v.id WHERE p.id='terms' AND p.current_version_id IS NULL AND NOT EXISTS (SELECT 1 FROM legal_policy_versions newer WHERE newer.policy_id=p.id AND newer.version_number>1);
    IF (SELECT COUNT(*)=2 FROM legal_policies p JOIN legal_policy_versions v ON v.id=p.current_version_id AND v.policy_id=p.id JOIN legal_policy_approvals a ON a.version_id=v.id WHERE v.state='published' AND v.published_at IS NOT NULL AND a.decision='approved' AND v.content_sha256=SHA2(v.content,256))<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='v10 contract: Both explicit current published policies require durable approval and matching source hash'; END IF;
    IF (SELECT COUNT(*)=0 FROM legal_policy_versions v LEFT JOIN legal_policy_approvals a ON a.version_id=v.id WHERE (v.state='published' AND (a.decision IS NULL OR a.decision<>'approved' OR v.published_at IS NULL)) OR v.content_sha256<>SHA2(v.content,256))<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='v10 contract: Published history and content integrity'; END IF;
    IF (SELECT COUNT(*) FROM legal_policy_versions v JOIN legal_policy_approvals a ON a.version_id=v.id WHERE v.policy_id='privacy' AND v.version_number=1 AND v.title='Privacy Policy' AND BINARY v.content_sha256='4d1c161153fa0892ccbb4133ec0ee6155378ef05823e45a9d894484471fcda31' AND v.state='published' AND a.decision='approved' AND a.approval_mode='bootstrap')<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='v10 contract: privacy v1 corrected approved seed'; END IF;
    IF (SELECT COUNT(*) FROM legal_policy_versions v JOIN legal_policy_approvals a ON a.version_id=v.id WHERE v.policy_id='terms' AND v.version_number=1 AND v.title='Terms of Service' AND BINARY v.content_sha256='4fabda0f307ed19036dea0af01db77a6ca0513911b7cfcbea20b1658e958aec8' AND v.state='published' AND a.decision='approved' AND a.approval_mode='bootstrap')<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='v10 contract: terms v1 corrected approved seed'; END IF;
    REPLACE INTO schema_meta(k,v) VALUES ('schema_version','10');
    COMMIT;
    DO RELEASE_LOCK('prism_migrate');
END$$
CALL prism_apply_schema_v10()$$
